SELECT nazwa, cena
FROM produkty
WHERE cena > 1000;

SELECT imie, nazwisko, rok_urodzenia
FROM uczniowie
WHERE rok_urodzenia BETWEEN 2007 AND 2008;

SELECT imie, nazwisko, email
FROM klienci
WHERE email LIKE '%@gmail.com';

SELECT DISTINCT miasto
FROM klienci
ORDER BY miasto;

UPDATE produkty
SET cena = cena * 1.1
WHERE kategoria_id = 3;

CREATE TABLE nauczyciele (
    id INTEGER PRIMARY KEY,
    imie TEXT NOT NULL,
    nazwisko TEXT NOT NULL,
    przedmiot_id INTEGER REFERENCES przedmioty(id)
);
